css:
:root{--ink:#0e1a24;--ink2:#1c2c3a;--steel:#5b6b78;--silver:#c9d1d8;--mist:#eef2f5;--white:#fff;--accent:#e8a317;--r:6px;--max:1180px}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:"Helvetica Neue",Arial,sans-serif;color:var(--ink);background:#fff;line-height:1.6}
a{color:inherit}img{max-width:100%;display:block}
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
section{padding:80px 0}
.eyebrow{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--steel);font-weight:600;margin-bottom:12px}
h1,h2,h3{line-height:1.15;letter-spacing:-.01em}
h1{font-size:clamp(36px,5vw,60px);font-weight:700}
h2{font-size:clamp(28px,3.4vw,40px);font-weight:700;margin-bottom:16px}
h3{font-size:20px;font-weight:600;margin-bottom:8px}
.lead{font-size:18px;color:var(--ink2);max-width:680px}
.btn{display:inline-block;padding:14px 26px;border-radius:var(--r);text-decoration:none;font-weight:600;font-size:15px}
.btn-p{background:var(--accent);color:var(--ink)}
.btn-g{border:1.5px solid currentColor;color:inherit;margin-left:12px}
.btn-d{background:var(--ink);color:#fff}
header{position:sticky;top:0;z-index:50;background:var(--ink);color:#fff}
.nav{display:flex;align-items:center;justify-content:space-between;height:72px;gap:24px}
.brand{font-weight:800;letter-spacing:.08em;text-transform:uppercase;text-decoration:none;font-size:16px;white-space:nowrap}
.brand span{color:var(--accent)}
.menu{display:flex;gap:22px;list-style:none;font-size:14px}
.menu a{text-decoration:none;opacity:.88}.menu a:hover{opacity:1;color:var(--accent)}
.nav-r{display:flex;align-items:center;gap:18px}
.nav-r .btn{padding:10px 18px;font-size:14px}
.hero{background:linear-gradient(135deg,var(--ink) 0%,var(--ink2) 60%,var(--steel) 100%);color:#fff;padding:96px 0 88px}
.hero .eyebrow{color:var(--silver)}
.hero .lead{color:var(--silver);margin:20px 0 32px}
.sub{background:var(--mist);padding:72px 0 64px}
.sub .lead{margin-top:6px}
.specs{background:var(--mist);padding:52px 0}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:20px;margin-top:40px}
.sg{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:20px;text-align:center}
.sv{font-size:32px;font-weight:800}.sl{font-size:13px;color:var(--steel)}
.card{border:1px solid var(--silver);border-radius:var(--r);padding:26px;text-decoration:none;display:block;transition:transform .2s,box-shadow .2s}
a.card:hover{transform:translateY(-3px);box-shadow:0 12px 28px rgba(14,26,36,.12)}
.card p{color:var(--steel);font-size:15px;margin-top:6px}
.card .tag{display:inline-block;font-size:12px;font-weight:700;color:var(--accent);margin-bottom:10px;letter-spacing:.06em}
.dark{background:var(--ink);color:#fff}.dark .eyebrow,.dark .lead,.dark .card p{color:var(--silver)}
.dark .card{border-color:var(--ink2);background:var(--ink2)}
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));border-top:2px solid var(--ink);margin-top:40px}
.step{padding:24px 20px 0 0}.step b{display:block;color:var(--accent);font-size:13px;margin-bottom:10px}
.step p{color:var(--steel);font-size:15px}
.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
.panel{background:var(--mist);border-radius:var(--r);padding:40px}
.ph{height:240px;border-radius:var(--r);background:linear-gradient(160deg,#7d8b96,#3a4855);margin-bottom:24px}
.big{font-size:90px;font-weight:800;line-height:1}.big span{color:var(--accent)}
.prose p{margin-bottom:16px;max-width:760px;color:var(--ink2)}
.prose ul{margin:0 0 16px 20px;color:var(--ink2);max-width:760px}
.prose li{margin-bottom:6px}
table{width:100%;border-collapse:collapse;max-width:760px;margin-top:20px}
td,th{text-align:left;padding:12px 14px;border-bottom:1px solid var(--silver);font-size:15px}
th{background:var(--mist);font-weight:600}
form .row{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}
form input,form select,form textarea{width:100%;padding:12px;border:1px solid var(--silver);border-radius:var(--r);font:inherit}
form textarea{min-height:120px}
form label{font-size:13px;color:var(--steel);display:block;margin-bottom:6px}
.cta{background:linear-gradient(135deg,var(--accent),#f3c25c);text-align:center;padding:84px 0}
.cta p{max-width:560px;margin:10px auto 28px;font-size:17px}
.certs{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin-top:32px}
.cert{border:1px solid var(--silver);border-radius:var(--r);padding:26px;text-align:center}
.cert strong{display:block;font-size:24px}.cert span{font-size:14px;color:var(--steel)}
.crumb{font-size:13px;color:var(--steel);margin-bottom:14px}.crumb a{text-decoration:none}
footer{background:var(--ink);color:var(--silver);padding:60px 0 28px;font-size:14px}
.fg{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:36px}
footer h4{color:#fff;font-size:12px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:14px}
footer ul{list-style:none}footer li{margin-bottom:8px}
footer a{text-decoration:none}footer a:hover{color:var(--accent)}
.fb{margin-top:44px;padding-top:22px;border-top:1px solid var(--ink2);display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;font-size:13px}
@media(max-width:860px){.menu{display:none}.split{grid-template-columns:1fr;gap:36px}.fg{grid-template-columns:1fr 1fr}.sub,section{padding:56px 0}form .row{grid-template-columns:1fr}}
